  selector: 'app-root',
  imports: [
    RouterOutlet,
    RouterLink,
    RouterLinkActive,
    NgIcon,
    HlmAvatar,
    HlmAvatarFallback,
    HlmSidebarImports,
    AppTopbar,
  ],
  providers: [
    ShellViewModel,
    provideIcons({
      lucideCrosshair,
      lucideLayoutDashboard,
      lucideSettings,
      lucideShieldAlert,
      lucideUserPlus,
      lucideUsers,
    }),
  ],
  templateUrl: './app.html',
  styleUrl: './app.css',
})
export class App {
  protected readonly vm = inject(ShellViewModel);
}

